with a as( select DISTINCT aa.process_main_id ,aa.should_inspect_num from ${inspectProcessDispatcherTable} aa where aa.delete_flag = false GROUP BY aa.process_main_id ,aa.should_inspect_num ) , b as( select a.process_main_id,sum(a.should_inspect_num) as should_inspect_num from a GROUP BY a.process_main_id ), c as( select cc.process_main_id, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as passed_num,sum(cc.un_passed_num) as un_passed_num from ${inspectProcessReportTable} cc GROUP BY cc.process_main_id ), d as( select aa.process_main_id,aa.inspect_type,string_agg(CAST(bb.staff_sign as TEXT),',') as inspectUserName from ${inspectProcessDispatcherTable} aa , ${staffTable} bb where aa.inspect_user_code = bb.primary_key GROUP BY aa.process_main_id,aa.inspect_type ) select * from ( select aa.main_id,aa.buss_number,aa.pcs_name,aa.create_time,aa.batch,aa.product_flag, aa.batch_num,aa.procedure_name,aa.procedure_code,aa.operator_user_code,aa.task_num,aa.overdue_date,aa.status,aa.remark,aa.primary_key as primaryKeyValue,aa.enterprise_code,aa.primary_key, b.should_inspect_num,c.inspect_num, c.passed_num , c.un_passed_num ,ROUND((c.passed_num/c.inspect_num) * 100,2) as passed_rate,d.inspectUserName,aa.check_items,d.inspect_type,e.status as approve_status from ${inspectProcessTable} aa LEFT JOIN b on aa.primary_key = b.process_main_id LEFT JOIN c on aa.primary_key = c.process_main_id LEFT JOIN d on aa.primary_key = d.process_main_id left join ${approveTable} e on aa.primary_key = e.inspect_main_id where aa.delete_flag = false ) t where t.enterprise_code = #{enterpriseCode}
AND (t.buss_number like concat('%', #{data.bussNumber}, '%') or t.batch like concat('%',#{data.bussNumber}, '%') )
AND t.procedure_name like concat('%',#{data.procedureName}, '%')
AND t.status = #{data.status}
AND t.overdue_date >= #{data.beginDate}
AND t.overdue_date <= #{data.endDate}
AND t.operator_user_code IN
#{userCode}
AND exists ( select 1 from ${inspectProcessDispatcherTable} b where b.inspect_user_code in
#{userCode}
and b.process_main_id=t.primary_key)
AND t.passed_rate >= #{data.passRate}
order by t.create_time desc

WITH t as( select cc.process_main_id, batch_no,status, sum(cc.inspect_num) as inspect_num ,sum(cc.passed_num) as passed_num,sum(cc.un_passed_num) as un_passed_num from ${inspectProcessReportTable} cc where cc.inspect_user = #{data.inspectUserCode[0]} and cc.delete_flag = false GROUP BY cc.process_main_id,batch_no,status ) select * from ( select b.buss_number,b.pcs_name,b.batch,b.product_flag, b.batch_num,b.procedure_name,b.procedure_code,b.operator_user_code,b.task_num,a.finish_date as overdue_date,t.status, a.remark,b.enterprise_code,b.create_time,b.check_items, t.inspect_num,t.passed_num,t.un_passed_num, ROUND((t.passed_num/t.inspect_num) * 100,2) as passed_rate, a.primary_key as primaryKeyValue,a.allocation_num as should_inspect_num,a.batch_no,a.process_main_id as mainId, e.status as approve_status from ${inspectProcessDispatcherTable} a LEFT JOIN ${inspectProcessTable} b on a.process_main_id = b.primary_key LEFT JOIN t on t.process_main_id = a.process_main_id and t.batch_no = a.batch_no left join ${approveTable} e on b.primary_key = e.inspect_main_id where a.inspect_user_code = #{data.inspectUserCode[0]} and a.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode}
AND (tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
AND tt.procedure_name like concat('%',#{data.procedureName}, '%')
AND (tt.status is null or tt.status = 30)
AND tt.status = #{data.status}
AND tt.overdue_date >= #{data.beginDate}
AND tt.overdue_date <= #{data.endDate}
AND tt.operator_user_code IN
#{userCode}
AND tt.passed_rate >= #{data.passRate}
order by tt.create_time desc

with t as (select process_main_id, a.should_inspect_num from ${inspectProcessDispatcherTable} a GROUP BY a.process_main_id, a.should_inspect_num) select * from( select b.batch_num,a.primary_key as primaryKeyValue, b.procedure_name,b.buss_number,b.batch,b.product_flag, b.operator_user_code,d.staff_sign as operatorUserName, b.task_num, b.overdue_date, t.should_inspect_num, a.finish_date, a.inspect_type, a.inspect_ratio, a.passed_num, a.inspect_num as inspectNum, a.un_passed_num, a.create_time, a.process_main_id as mainId, a.batch_no, a.inspect_user,c.staff_sign as inspectUserName, a.enterprise_code, a.remark, ROUND((a.passed_num/a.inspect_num) * 100,2) as pass_rate from ${inspectProcessReportTable} a inner join t on t.process_main_id = a.process_main_id LEFT JOIN ${inspectProcessTable} b on a.process_main_id = b.primary_key LEFT JOIN ${staffTable} c on a.inspect_user = c.primary_key LEFT JOIN ${staffTable} d on b.operator_user_code = d.primary_key where a.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode}
AND (tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
AND tt.procedure_name like concat('%',#{data.procedureName}, '%')
AND tt.create_time >= #{data.beginDate}
AND tt.create_time <= #{data.endDate}
AND tt.operator_user_code IN
#{userCode}
AND tt.inspect_user in
#{userCode}
AND tt.pass_rate >= #{data.passRate}
AND primaryKeyValue IN
#{code}
order by MAX(tt.create_time) OVER (PARTITION BY tt.mainId) DESC, tt.mainId, tt.create_time desc
LIMIT #{data.pageSize} OFFSET #{data.offset}

with t as ( select process_main_id, sum(a.allocation_num) as should_inspect_num from ${inspectProcessDispatcherTable} a where a.enterprise_code = #{enterpriseCode} and a.inspect_user_code = #{data.inspectUserCode[0]} GROUP BY process_main_id ) select * from( select b.batch_num,a.primary_key as primaryKeyValue, b.procedure_name,b.buss_number,b.batch,b.product_flag, b.operator_user_code,d.staff_sign as operatorUserName, b.task_num, b.overdue_date, t.should_inspect_num, a.finish_date, a.inspect_type, a.inspect_ratio, a.passed_num, a.inspect_num, a.un_passed_num, a.create_time, a.process_main_id as mainId, a.batch_no, a.inspect_user,c.staff_sign as inspectUserName, a.enterprise_code, a.remark, ROUND((a.passed_num/a.inspect_num) * 100,2) as pass_rate from ${inspectProcessReportTable} a inner join t on t.process_main_id = a.process_main_id LEFT JOIN ${inspectProcessTable} b on a.process_main_id = b.primary_key LEFT JOIN ${staffTable} c on a.inspect_user = c.primary_key LEFT JOIN ${staffTable} d on b.operator_user_code = d.primary_key where a.delete_flag = false )tt where tt.enterprise_code = #{enterpriseCode} and tt.inspect_user = #{data.inspectUserCode[0]}
AND (tt.buss_number like concat('%', #{data.bussNumber}, '%') or tt.batch like concat('%',#{data.bussNumber}, '%') )
AND tt.procedure_name like concat('%',#{data.procedureName}, '%')
AND tt.create_time >= #{data.beginDate}
AND tt.create_time <= #{data.endDate}
AND tt.operator_user_code IN
#{userCode}
AND tt.pass_rate >= #{data.passRate}
AND primaryKeyValue IN
#{code}
order by MAX(tt.create_time) OVER (PARTITION BY tt.mainId) DESC, tt.mainId, tt.create_time desc
limit #{data.limitNum}

